#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
echo '=== File and Directory Operations ==='
d="$(mktemp -d)"
cd "$d" || exit 1
printf 'a\n' >a.sh
printf 'b\n' >b.txt
mkdir sub
printf 'c\n' >sub/c.sh
printf 'x\n' >.hidden
file_list="$(ls -A | sort)"
echo 'File listing:'
printf '%s\n' "$file_list"
found_files="$(find . -name '*.sh' -type f)"
echo 'Found shell scripts:'
printf '%s\n' "$found_files"
cd /
rm -r -f "$d"
echo '=== File and Directory Operations Complete ==='
